  if(withTransition) action.transition={type:"DISSOLVE",duration:0.3,easing:{type:"EASE_OUT"}};
  try{ node.reactions=[{trigger:{type:"ON_CLICK"},actions:[action]}]; out[label]="ok"; }
  catch(e){ out[label]="err:"+String(e.message).slice(0,110); }
}
